class ProductCatalog:
    def __init__(self, name, users=None, products=None):
        self.name = name
        self.users = users if users is not None else []
        self.products = products if products is not None else {}

    def hire_user(self, new_user):
        self.users.append(new_user)

    def add_product(self, new_product):
        if new_product in self.products:
            print(f'{self.name} already has this product!')
        else:
            self.products[new_product] = ''

    def purchase_product(self, product, user_name):
        if product in self.products:
            self.products[product] = user_name
        else:
            print(f'Sorry, we don’t have {product}.')

    def return_product(self, product):
        if product in self.products:
            self.products[product] = ''
        else:
            print('Sorry, wrong catalog.')

    def __str__(self):
        return self.name

def next_shipment_size(n):
    if n == 1:
        return 2
    elif n == 2:
        return 3
    else:
        return next_shipment_size(n - 1) * next_shipment_size(n - 2)

def get_latest_entry_time(entry_times):
    if len(entry_times) == 1:
        return entry_times[0]
    else:
        return max(entry_times[0], get_latest_entry_time(entry_times[1:]))

def reverse_itinerary(cities):
    if len(cities) == 0:
        return []
    return [cities[-1]] + reverse_itinerary(cities[:-1])

def separate_transactions(transactions):
    if not transactions:
        return []
    first, *rest = transactions
    if first >= 0:
        return [first] + separate_transactions(rest)
    else:
        return separate_transactions(rest) + [first]
